"""Independent arithmetic and output comparisons; standalone public consumer."""
exec(compile("#!/usr/bin/env python3\n# Literal independent calculation, no import from production and no reading its inputs.\nimport json\n\ndef literal(margin_change=0,r=.10):\n    revenue=[34.3,36.7,39.3,41.8,44.2];margins=[.151,.153,.155,.155,.154];da=[1.6,1.75,1.9,2.05,2.2];capex=[3.6,3.5,3.3,3.1,3.1];wc=[.5,.55,.6,.6,.6]\n    cash=13.62726641447+.94976587324+.917995-.057184368-.0073784-.03068077627-.01815410725-.02156603859-.14066-.0071335-.010146686\n    debt=3.93330853806;minor=.16;d=[];need=3.3;frac=69575380.74/3136869701.89\n    for i in range(5):\n        n=revenue[i]*(margins[i]+margin_change)*.84\n        flow=n+da[i]-capex[i]-wc[i]\n        inc=(cash-need)*.015;interest=debt*.03*.84\n        payout=((n+inc-interest)*(1-frac)-[.244,.244,.2430296258,0,0][i])*.4\n        md=n*frac*.15\n        minor+=flow*frac+minor*.015-md\n        repayment=min(debt,[1.2,1.2,1.2,.33330853806,0][i]);debt-=repayment\n        cash+=flow+inc-interest-repayment-(.19204866216 if i==0 else 0)-md-payout\n        d.append(payout/4.207365435);need=revenue[i]*.1\n    excess=cash-need-minor\n    financial=sum((excess/10+(excess-j*excess/10)*.015)/(1+r)**(j+1) for j in range(10))\n    tail=sum((n*1.04**j*.75)/(1+r)**j for j in range(1,6))+(n*1.04**5*1.025*(1-.025/.14)/(r-.025))/(1+r)**5\n    terminal=(tail*(1-frac)+financial-debt)/4.207365435\n    pv=sum(v/(1+r)**(i+1) for i,v in enumerate(d))+terminal/(1+r)**5\n    return dict(value=pv,terminal=terminal,dps=d,cash=cash,financial=financial,minor=minor,tail=tail)\nres={'base_low':literal(),'base_high':literal(r=.09),'margin_minus_1pct_low':literal(-.01)}\nprint(json.dumps(res,indent=2))\n", __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
exec(compile("from pathlib import Path\nfrom decimal import Decimal as D,getcontext\nimport json\ngetcontext().prec=35\ndef d(v):return D(str(v))\nz=d(0);shares=d('4.207365435');minor=d('69575380.74')/d('3136869701.89')\ndef calc(shift=z):\n cash=sum(map(d,['13.62726641447','.94976587324','.917995']))-sum(map(d,['.057184368','.0073784','.03068077627','.01815410725','.02156603859','.14066','.0071335','.010146686']));debt=sum(map(d,['1.54691094311','.99896272274','1.23492','.15251487221']));mc=d('6.5');mp=d('.78460581691')-d('.50329943904');res=d('1.17290878487');mi=d('.16');need=d('3.3');rows=[]\n for i in range(5):\n  rev=d([34.3,36.7,39.3,41.8,44.2][i]);margin=d([.151,.153,.155,.155,.154][i])+shift;da=d([1.6,1.75,1.9,2.05,2.2][i]);cap=d([3.6,3.5,3.3,3.1,3.1][i]);wc=d([.50,.55,.60,.60,.60][i]);grant=d([.244,.244,.2430296258,0,0][i]);nop=rev*margin*d('.84');fcf=nop+da-cap-wc;interest=debt*d('.03')*d('.84');fin=max(cash-need,z)*d('.015');ni=nop-interest+fin;common=ni*(1-minor)-grant;newneed=rev*d('.1')\n  nci_div=nop*minor*d('.15');newmi=mi+fcf*minor+max(mi,z)*d('.015')-nci_div;repay=min(debt,d([1.2,1.2,1.2,.33330853806,0][i]));buy=d('.19204866216') if i==0 else z;pre=cash+fcf+fin-interest-repay-buy-nci_div\n  own=nop*d('.14');subprofit=max(nop*(1-minor)-own,z);mf=max(mc-d('1.2'),z)*d('.015');mint=interest*d('.6');parentpre=mc+fcf*d('.12')+mf-mint-repay*d('.6')-buy-d('.45');subpre=pre-parentpre;submin=max(newneed-d('1.2'),z)+max(newmi,z);up=min(subprofit*d('.38'),max(subpre-submin,z));parentpre+=up\n  income=own+up+mf-mint-grant;sr=min(max(income,z)*d('.1'),max(shares*d('.5')-res,z));res+=sr;available=max(mp+income-sr,z);div=min(max(common*d('.4'),z),available,max(parentpre-d('1.2'),z),max(pre-newneed-newmi,z));mc=parentpre-div;cash=pre-div;mp=mp+income-sr-div;debt-=repay;mi=newmi;need=newneed\n  rows.append(dict(nopat=nop,fcf=fcf,dividend=div,cash_end=cash,mother_cash_end=mc,mother_retained_end=mp,mother_reserve_end=res,minor_financial_end=mi,upstream=up,debt_end=debt))\n vals=[]\n for rate in [d('.1'),d('.09')]:\n  n=rows[-1]['nopat'];ev=z\n  for t in range(1,6):n*=d('1.04');ev+=n*(1-d('.04')/d('.16'))/(1+rate)**t\n  ev+=n*d('1.025')*(1-d('.025')/d('.14'))/(rate-d('.025'))/(1+rate)**5\n  excess=cash-need-mi;asset=sum((excess/10+(excess-excess*j/10)*d('.015'))/(1+rate)**(j+1) for j in range(10));tv=((1-minor)*ev+asset-debt)/shares;value=sum(x['dividend']/shares/(1+rate)**(j+1)for j,x in enumerate(rows))+tv/(1+rate)**5;vals.append((value,tv))\n return rows,vals\np=json.load(open(str(Path(__file__).resolve().parent / '2026-Q3-output.json')));out=[]\nfor name,shift in [('base',z),('margin_minus_1pct',d('-.01'))]:\n rows,values=calc(shift);prod=p['scenarios'][name];err=[]\n for a,b in zip(rows,prod['rows']):\n  for k,v in a.items():err.append(abs(float(v)-b[k]))\n assert max(err)<1e-10\n for vals,b in zip(values,prod['valuation']):\n  assert b['asset_release_years']==10\n  assert abs(float(vals[0])-b['value'])<1e-10\n  assert abs(float(vals[1])-b['terminal'])<1e-10\n out.append({'case':name,'annual_fields':len(err),'max_error':max(err),'value_tv':[[str(v)for v in x]for x in values]})\nprint(json.dumps(out,ensure_ascii=False,indent=2))\n", __file__, "exec"), {"__file__": __file__, "__name__": "__main__"})
